def test_dedupe_sessions_keeps_last_occurrence_and_sorts():
    earlier_record = {"id": "a", "day": 8, "converted": True}
    last_record = {"id": "a", "day": 2, "converted": False}
    same_day = {"id": "b", "day": 2, "converted": True}
    first_day = {"id": "c", "day": 1, "converted": None}
    assert dedupe_sessions([earlier_record, same_day, first_day, last_record]) == [
        first_day, last_record, same_day,
    ]


def test_daily_conversion_counts_includes_empty_days_and_range_endpoints():
